// 입력 데이터 분석 및 라우팅 결정
const inputData = $input.all()[0].json;

// 기본 데이터가 없으면 샘플 생성
const data = inputData.data || {
  type: 'user',
  priority: 'high',
  value: 850,
  category: 'premium'
};

// 라우팅 조건들
const conditions = {
  isHighPriority: data.priority === 'high',
  isLargeValue: data.value > 1000,
  isPremium: data.category === 'premium',
  isUser: data.type === 'user'
};

// 라우팅 결정 로직
let route = 'default';
let routeReason = 'Default processing';

if (conditions.isHighPriority && conditions.isPremium) {
  route = 'premium-priority';
  routeReason = 'High priority premium customer';
} else if (conditions.isLargeValue) {
  route = 'high-value';
  routeReason = 'High value transaction';
} else if (conditions.isUser && conditions.isPremium) {
  route = 'premium-user';
  routeReason = 'Premium user processing';
} else if (conditions.isHighPriority) {
  route = 'priority';
  routeReason = 'High priority processing';
}

return [{
  json: {
    originalData: data,
    conditions: conditions,
    selectedRoute: route,
    routeReason: routeReason,
    timestamp: new Date().toISOString()
  }
}];

// 프리미엄 우선순위 처리
const data = $input.all()[0].json;

const result = {
  route: 'premium-priority',
  processing: {
    priorityLevel: 'URGENT',
    serviceLevel: 'PREMIUM',
    estimatedTime: '< 5 minutes',
    specialHandling: true,
    assignedAgent: 'Senior Specialist',
    benefits: ['Fast track', 'Dedicated support', 'Priority queue']
  },
  data: data.originalData,
  processedAt: new Date().toISOString(),
  status: 'PREMIUM_PROCESSED'
};

return [{ json: result }];

// 고액 거래 처리
const data = $input.all()[0].json;

const result = {
  route: 'high-value',
  processing: {
    priorityLevel: 'HIGH',
    serviceLevel: 'STANDARD',
    estimatedTime: '10-15 minutes',
    verificationRequired: true,
    approvalNeeded: data.originalData.value > 5000,
    riskAssessment: data.originalData.value > 10000 ? 'HIGH' : 'MEDIUM'
  },
  data: data.originalData,
  processedAt: new Date().toISOString(),
  status: 'HIGH_VALUE_PROCESSED'
};

return [{ json: result }];

// 일반 처리
const data = $input.all()[0].json;

const result = {
  route: data.selectedRoute || 'default',
  processing: {
    priorityLevel: 'NORMAL',
    serviceLevel: 'STANDARD',
    estimatedTime: '15-30 minutes',
    automaticProcessing: true,
    queuePosition: Math.floor(Math.random() * 50) + 1
  },
  data: data.originalData,
  processedAt: new Date().toISOString(),
  status: 'STANDARD_PROCESSED'
};

return [{ json: result }];

// 모든 처리 경로의 결과를 통합
const allInputs = $input.all();
const processedData = allInputs[0].json;

// 라우팅 통계
const routingStats = {
  totalRoutes: 4,
  usedRoute: processedData.route,
  processingTime: new Date().toISOString(),
  efficiency: processedData.processing.priorityLevel === 'URGENT' ? '최고' : 
              processedData.processing.priorityLevel === 'HIGH' ? '높음' : '보통'
};

// 최종 결과
const finalResult = {
  summary: {
    route: processedData.route,
    status: processedData.status,
    efficiency: routingStats.efficiency,
    completedAt: new Date().toISOString()
  },
  routing: routingStats,
  processing: processedData.processing,
  originalData: processedData.data,
  systemInfo: {
    workflowName: 'Conditional Router',
    version: '1.0.0',
    executionId: Math.random().toString(36).substr(2, 9)
  }
};

return [{ json: finalResult }];
